/**
 * Code generator: writes `src/generated/*` from content type definitions.
 * Everything in that folder is overwritten on each run; custom code lives in `src/extensions`.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import type { ContentTypeDefinition, FieldDefinition, PhysicalColumn } from '@opencms/schema';
import {
  fieldStorage,
  isMultiRelation,
  l10nBaseColumns,
  l10nTable,
  mainBaseColumns,
  mainTable,
  relBaseColumns,
} from '@opencms/schema';

const HEADER = `// ------------------------------------------------------------------
// Generated by opencms-cli. DO NOT EDIT: changes are overwritten.
// Edit src/content-types/**/*.schema.ts and run \`opencms generate\`.
// ------------------------------------------------------------------
`;

export const pascal = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

function tsFieldType(field: FieldDefinition): string {
  switch (field.kind) {
    case 'number':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'richText':
      return 'RichTextDocument';
    case 'json':
      return 'unknown';
    case 'money':
      return 'Money';
    case 'asset':
    case 'reference':
    case 'taxonomy':
      return isMultiRelation(field) ? 'string[]' : 'string';
    default:
      return 'string';
  }
}

function fieldDoc(field: FieldDefinition): string {
  const bits: string[] = [field.kind];
  if (field.required) bits.push('required');
  if (field.localizable) bits.push('localizable');
  if (field.unique) bits.push('unique');
  else if (field.indexed) bits.push('indexed');
  const o = field.options as Record<string, unknown>;
  if (o.target) bits.push(`-> ${o.target}`);
  const label = field.label ? `${field.label}. ` : '';
  return `  /** ${label}${bits.join(', ')} */`;
}

function renderTypes(defs: ContentTypeDefinition[]): string {
  const out: string[] = [
    HEADER,
    'export type RichTextDocument = Record<string, unknown> | unknown[];',
    'export interface Money { amount: number; currency: string }',
    '',
    'export interface EntryMeta {',
    '  documentId: string;',
    "  status: 'draft' | 'published';",
    '  locale: string | null;',
    '  createdAt: string;',
    '  updatedAt: string;',
    '  publishedAt: string | null;',
    '}',
    '',
  ];
  for (const def of defs) {
    const name = pascal(def.apiId);
    out.push(`/** ${def.displayName} (${def.apiId}) */`);
    out.push(`export interface ${name} extends EntryMeta {`);
    for (const field of def.fields) {
      out.push(fieldDoc(field));
      const t = tsFieldType(field);
      out.push(isMultiRelation(field) ? `  ${field.name}: ${t};` : `  ${field.name}: ${t} | null;`);
    }
    out.push('}', '');
    out.push(`export interface ${name}Input {`);
    for (const field of def.fields) out.push(`  ${field.name}?: ${tsFieldType(field)} | null;`);
    out.push('}', '');
  }
  out.push('export interface ContentTypeMap {');
  for (const def of defs) out.push(`  ${def.apiId}: ${pascal(def.apiId)};`);
  out.push('}', '');
  out.push('export interface ContentTypeInputMap {');
  for (const def of defs) out.push(`  ${def.apiId}: ${pascal(def.apiId)}Input;`);
  out.push('}', '');
  return out.join('\n');
}

function pgToTs(col: PhysicalColumn): string {
  const t = col.type;
  let ts = 'string';
  if (t === 'integer') ts = 'number';
  else if (t === 'boolean') ts = 'boolean';
  else if (t === 'timestamptz' || t === 'date') ts = 'Date';
  else if (t === 'jsonb') ts = 'unknown';
  else if (t.startsWith('numeric')) ts = 'string';
  return col.notNull ? ts : `${ts} | null`;
}

function tableInterface(name: string, columns: PhysicalColumn[]): string {
  return [`export interface ${name} {`, ...columns.map((c) => `  ${c.name}: ${pgToTs(c)};`), '}', ''].join('\n');
}

function renderTables(defs: ContentTypeDefinition[]): string {
  const out: string[] = [HEADER, '/** Kysely table types for the generated ct_* tables. */', ''];
  const dbEntries: string[] = [];
  for (const def of defs) {
    const base = pascal(def.apiId);
    const mainCols = [...mainBaseColumns()];
    const l10nCols = [...l10nBaseColumns(def)];
    for (const field of def.fields) {
      const s = fieldStorage(def, field);
      if (s.mode === 'columns') (s.location === 'main' ? mainCols : l10nCols).push(...s.columns);
      else {
        const iface = `${base}${pascal(field.name)}RelTable`;
        out.push(tableInterface(iface, relBaseColumns(def, field)));
        dbEntries.push(`  ${s.table}: ${iface};`);
      }
    }
    out.push(tableInterface(`${base}Table`, mainCols));
    out.push(tableInterface(`${base}L10nTable`, l10nCols));
    dbEntries.unshift(`  ${mainTable(def)}: ${base}Table;`, `  ${l10nTable(def)}: ${base}L10nTable;`);
  }
  out.push('export interface ContentDatabase {', ...dbEntries, '}', '');
  return out.join('\n');
}

function renderRegistry(defs: ContentTypeDefinition[]): string {
  const out: string[] = [HEADER, "import type { ContentTypeDefinition } from '@opencms/schema';", ''];
  for (const def of defs) {
    out.push(`export const ${def.apiId}Definition: ContentTypeDefinition = ${JSON.stringify(def, null, 2)};`, '');
  }
  out.push(`export const contentTypes: ContentTypeDefinition[] = [${defs.map((d) => `${d.apiId}Definition`).join(', ')}];`, '');
  return out.join('\n');
}

function renderValidators(defs: ContentTypeDefinition[]): string {
  const out: string[] = [
    HEADER,
    "import { buildEntryValidator } from '@opencms/schema';",
    `import { ${defs.map((d) => `${d.apiId}Definition`).join(', ')} } from './registry';`,
    '',
  ];
  if (!defs.length) out.splice(2, 1);
  for (const def of defs) {
    out.push(`export const ${def.apiId}DraftSchema = buildEntryValidator(${def.apiId}Definition, 'draft');`);
    out.push(`export const ${def.apiId}PublishSchema = buildEntryValidator(${def.apiId}Definition, 'publish');`);
  }
  out.push('');
  return out.join('\n');
}

function renderIndex(): string {
  return `${HEADER}export * from './types';\nexport * from './tables';\nexport * from './registry';\nexport * from './validators';\n`;
}

export interface GeneratedFile {
  path: string;
  content: string;
}

export function generateCode(defs: ContentTypeDefinition[], generatedDir: string): GeneratedFile[] {
  const sorted = [...defs].sort((a, b) => a.apiId.localeCompare(b.apiId));
  return [
    { path: path.join(generatedDir, 'types.ts'), content: renderTypes(sorted) },
    { path: path.join(generatedDir, 'tables.ts'), content: renderTables(sorted) },
    { path: path.join(generatedDir, 'registry.ts'), content: renderRegistry(sorted) },
    { path: path.join(generatedDir, 'validators.ts'), content: renderValidators(sorted) },
    { path: path.join(generatedDir, 'index.ts'), content: renderIndex() },
  ];
}

/** Writes files; returns the ones whose content changed. */
export function writeGeneratedFiles(files: GeneratedFile[]): string[] {
  const changed: string[] = [];
  for (const file of files) {
    const current = fs.existsSync(file.path) ? fs.readFileSync(file.path, 'utf8') : null;
    if (current === file.content) continue;
    fs.mkdirSync(path.dirname(file.path), { recursive: true });
    fs.writeFileSync(file.path, file.content);
    changed.push(file.path);
  }
  return changed;
}

export function staleGeneratedFiles(files: GeneratedFile[]): string[] {
  return files
    .filter((f) => !fs.existsSync(f.path) || fs.readFileSync(f.path, 'utf8') !== f.content)
    .map((f) => f.path);
}
